            "২. ইগো (Ego): এটি বাস্তব সত্তা। এটি 'বাস্তবতার নীতি' (Reality Principle) দ্বারা পরিচালিত হয় এবং ইদের অন্ধ চাহিদাকে বাস্তব সম্মত উপায়ে মেটানোর চেষ্টা করে।",
            "৩. সুপার-ইগো (Super-ego): এটি নৈতিক ও বিবেকী সত্তা। সমাজ, ধর্ম ও পারিবারিক শিক্ষা থেকে এটি গড়ে ওঠে এবং সঠিক-ভুলের মানদণ্ড নির্ধারণ করে।"
